use std::process::exit;

use wgpu::util::DeviceExt;

const SHADER: &str = r#"
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> hist: array<atomic<u32>, 256>;

var<workgroup> local_hist: array<atomic<u32>, 256>;

@compute @workgroup_size(256)
fn main(
    @builtin(local_invocation_index) lid: u32,
    @builtin(workgroup_id) wid: vec3<u32>,
    @builtin(num_workgroups) nwg: vec3<u32>,
) {
    atomicStore(&local_hist[lid], 0u);
    workgroupBarrier();

    let i = (wid.y * nwg.x + wid.x) * 256u + lid;
    if (i < params.count) {
        let a = ((i % 40000u) * 1597u + params.seed + 51749u) % 40000u;
        let b = (a * a + a * 37u + 11u) % 40009u;
        let c = (b * 613u + 7919u) % 40009u;
        let d = (c + (i / 40000u) * 7919u) % 40009u;
        let value = d % 1000u;
        let bin = value * params.bins / 1000u;
        atomicAdd(&local_hist[bin], 1u);
    }
    workgroupBarrier();

    let n = atomicLoad(&local_hist[lid]);
    if (n != 0u) {
        atomicAdd(&hist[lid], n);
    }
}
"#;

fn parse_input(path: &str) -> Option<(u32, u32, u32)> {
    let text = std::fs::read_to_string(path).ok()?;
    let mut it = text.split_whitespace().map(|s| s.parse::<u32>().ok());
    let count = it.next()??;
    let seed = it.next()??;
    let bins = it.next()??;
    Some((count, seed, bins))
}

fn run(count: u32, seed: u32, bins: u32) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("histogram"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let params: [u32; 4] = [count, seed, bins, 0];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let hist_size = 256 * 4;
    let hist_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("hist"),
        contents: &[0u8; 256 * 4],
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
    });
    let read_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: hist_size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: None,
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: params_buf.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 1, resource: hist_buf.as_entire_binding() },
        ],
    });

    let groups = count.div_ceil(256);
    // Spread over x and y so the 65535-per-dimension limit is never hit.
    let gx = groups.clamp(1, 4096);
    let gy = groups.div_ceil(gx).max(1);

