    if count > 0 {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(gx, gy, 1);
    }
    encoder.copy_buffer_to_buffer(&hist_buf, 0, &read_buf, 0, hist_size);
    queue.submit(Some(encoder.finish()));

    let slice = read_buf.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll failed: {e:?}"))?;
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    let out: Vec<u32> = bytemuck::cast_slice::<u8, u32>(&data).to_vec();
    drop(data);
    read_buf.unmap();
    Ok(out)
}

fn main() {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_histogram <input-file>");
        exit(2);
    };
    let Some((count, seed, bins)) = parse_input(&path) else {
        eprintln!("could not parse input file");
        exit(2);
    };
    if !(1..=256).contains(&bins) {
        eprintln!("bins out of range");
        exit(2);
    }
    match run(count, seed, bins) {
        Ok(hist) => {
            let mut out = String::new();
            for (i, n) in hist.iter().take(bins as usize).enumerate() {
                out.push_str(&format!("BIN {i} {n}\n"));
            }
            out.push_str(&format!("TOTAL {count}\n"));
            print!("{out}");
        }
        Err(e) => {
            eprintln!("{e}");
            exit(1);
        }
    }
}
